/* tf — 원고: ~/Documents/Study/서재_원고/tf.py 에서 생성(한/영 동시). 직접 고치지 말고 원고를 고친다. */
export const sections = [{"id": "guide", "title": "문서 안내", "sub": "0장", "part": "시작", "html": "<header class=\"g-cover\"><div class=\"g-kicker\">학습서 · 인프라</div><h1>테라폼, 클릭 대신 설계도로</h1><p class=\"g-lead\">클라우드를 클릭이 아니라 파일로 관리하는 이유와, 미리보기(plan)를 읽는 법, 장부(state)와 손수정 적발, 안전장치, 도입 순서, AI에게 시키는 법까지 한 틀로 익혀요.</p><div class=\"g-chips\"><span class=\"g-chip\">중학생도 읽는 설명</span><span class=\"g-chip\">plan 읽기</span><span class=\"g-chip\">실패 케이스</span><span class=\"g-chip\">한/영</span></div></header><div class=\"g-chapter\" id=\"g-tf-guide\"><h3><span class=\"g-cn\">00</span>문서 안내</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>이 책은 테라폼을 처음 접하는 사람이 「무엇이고, 왜 필요하고, 어디서 어떻게 깨지는가」를 같은 틀로 익히도록 쓴 학습서다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>명령어만 외우면 plan에 「삭제」가 떠도 무엇이 위험한지 알아보지 못한다.</div><section class=\"g-topic\"><h4>1.1 목적과 범위</h4><p>대상은 클라우드를 콘솔에서 클릭으로 다뤄 본 사람이다. 범위는 「설계도 작성 → plan 읽기 → 적용 → 장부 관리 → 안전장치 → 도입」이다. 코드 문법 전부를 외우는 것은 목표가 아니고, <b>plan을 읽고 승인·거절을 판단하는 능력</b>이 목표다.</p><p>모든 예시는 학습용 가짜 이름(my-project 등)이며 실제 회사 자원과 무관하다.</p></section><section class=\"g-topic\"><h4>1.2 장의 구조</h4><div class=\"g-tw\"><table><tr><th>요소</th><th>무엇을 답하나</th></tr><tr><td class=\"g-h\">정의</td><td>한 문장으로 무엇인가</td></tr><tr><td class=\"g-h\">이게 없으면</td><td>왜 필요한가</td></tr><tr><td class=\"g-h\">동작 원리</td><td>그림과 숫자 예시</td></tr><tr><td class=\"g-h\">단계 카드</td><td>입력·출력·담당·실패를 눌러서 펼침</td></tr><tr><td class=\"g-h\">실패 케이스</td><td>어디서 어떻게 깨지는가</td></tr><tr><td class=\"g-h\">코드 · 키워드</td><td>심화. AI에게 시킬 때 넣을 말</td></tr><tr><td class=\"g-h\">다루지 않는 것</td><td>경계를 숨기지 않는다</td></tr></table></div></section><section class=\"g-topic\"><h4>1.3 표기와 기준 시점</h4><div class=\"g-tw\"><table><tr><th>배지</th><th>뜻</th></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-ok\">실습으로 확인 가능</span></td><td>개인 테스트 프로젝트에서 직접 해 볼 수 있다</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-warn\">개념만 다룸</span></td><td>개념과 판단 기준만 다룬다</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-danger\">상황에 따라 다름</span></td><td>팀·상황에 따라 답이 달라진다</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></td><td>이 책에서 다루지 않는다</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-fill\">심화</span></td><td>코드가 나오는 심화 구간</td></tr></table></div><p>2026-10-15 기준. 명령·옵션은 버전마다 달라지므로 공식 문서(9장)로 다시 확인한다. <code>import</code> 블록은 Terraform 1.5 이상이다.</p></section></div>"}, {"id": "overview", "title": "큰 그림", "sub": "1장", "part": "기초", "html": "<div class=\"g-chapter\" id=\"g-tf-overview\"><h3><span class=\"g-cn\">01</span>큰 그림 — 클릭 대신 설계도로</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>테라폼은 클라우드에 있어야 할 자원을 파일(설계도)로 적어 두면, 도구가 실제 상태를 그 설계도에 맞춰 주는 방식(IaC, 코드로 관리하는 인프라)이다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>클릭으로 바꾸면 기록이 남지 않아 같은 환경을 다시 만들 수 없고, 누가 언제 무엇을 바꿨는지 모른다. 고치는 시간보다 알아차리는 시간이 훨씬 길어진다.</div><section class=\"g-topic\"><h4>1.1 동작 원리</h4><p>클릭 방식은 설명서 없이 레고를 손으로 조립하는 것과 같다. 설계도 방식은 설명서를 먼저 쓰고, 설명서대로 조립하며, 누가 몰래 블록을 바꾸면 설명서와 비교해 바로 찾아낸다.</p><figure><svg viewBox=\"0 0 720 296\" role=\"img\" aria-label=\"클릭 방식과 설계도 방식\"><rect x=\"6\" y=\"6\" width=\"340\" height=\"284\" rx=\"10\" class=\"g-zone\"/><rect x=\"374\" y=\"6\" width=\"340\" height=\"284\" rx=\"10\" class=\"g-zone g-zone2\"/><text x=\"22\" y=\"30\" text-anchor=\"start\" class=\"g-ts2\">콘솔에서 클릭</text><text x=\"390\" y=\"30\" text-anchor=\"start\" class=\"g-ts2\">설계도로 관리</text><rect x=\"24\" y=\"46\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fb\"/><text x=\"176\" y=\"74\" text-anchor=\"middle\" class=\"g-t\">클릭으로 변경</text><rect x=\"392\" y=\"46\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fas\"/><text x=\"544\" y=\"74\" text-anchor=\"middle\" class=\"g-t\">설계도 파일 수정</text><rect x=\"24\" y=\"106\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fb\"/><text x=\"176\" y=\"134\" text-anchor=\"middle\" class=\"g-t\">바로 반영</text><rect x=\"392\" y=\"106\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fw\"/><text x=\"544\" y=\"134\" text-anchor=\"middle\" class=\"g-t\">plan: 바뀔 목록</text><rect x=\"24\" y=\"166\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fh\"/><text x=\"176\" y=\"194\" text-anchor=\"middle\" class=\"g-t\">기록이 안 남음</text><rect x=\"392\" y=\"166\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fb\"/><text x=\"544\" y=\"194\" text-anchor=\"middle\" class=\"g-t\">사람이 승인</text><rect x=\"24\" y=\"226\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fh\"/><text x=\"176\" y=\"254\" text-anchor=\"middle\" class=\"g-t\">며칠 뒤 발견</text><rect x=\"392\" y=\"226\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fo\"/><text x=\"544\" y=\"254\" text-anchor=\"middle\" class=\"g-t\">apply 후 이력 보관</text></svg><figcaption><b>그림 1-1</b> 같은 변경이라도 설계도 방식은 「미리 보고, 승인하고, 기록이 남는다」</figcaption></figure><figure><svg viewBox=\"0 0 720 144\" role=\"img\" aria-label=\"테라폼 작업 흐름\"><rect x=\"6\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fas\"/><text x=\"66\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">설계도 수정</text><text x=\"66\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">.tf</text><path d=\"M129,51 L151,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"153\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fw\"/><text x=\"213\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">plan</text><text x=\"213\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">미리보기</text><path d=\"M276,51 L298,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"300\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fb\"/><text x=\"360\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">승인</text><text x=\"360\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">사람</text><path d=\"M422,51 L444,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"446\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fo\"/><text x=\"507\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">apply</text><text x=\"507\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">반영</text><path d=\"M569,51 L591,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"593\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fo\"/><text x=\"654\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">클라우드</text><text x=\"654\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">실제 자원</text><path d=\"M654,90 C654,132 213,132 213,92\" class=\"g-fla g-fd\" marker-end=\"url(#g-aha)\"/><text x=\"433\" y=\"128\" text-anchor=\"middle\" class=\"g-ts2\">state(장부): 지금 실제로 무엇이 있는지 기록 → 다음 plan 때 비교</text></svg><figcaption><b>그림 1-2</b> 핵심은 코드가 아니라 plan(미리보기)이다</figcaption></figure></section><section class=\"g-topic\"><h4>1.2 숫자 예시 — 변경 한 번의 요약</h4><div class=\"g-tw\"><table><tr><th>plan 마지막 줄</th><th>읽는 법</th></tr><tr><td class=\"g-h\"><code>Plan: 1 to add, 1 to change, 0 to destroy.</code></td><td>새로 만들 것 1개, 고칠 것 1개, <b>지울 것 0개</b> → 승인해도 안전한 편</td></tr><tr><td class=\"g-h\"><code>Plan: 0 to add, 0 to change, 1 to destroy.</code></td><td>지울 것이 있다 → 무엇을 왜 지우는지 확인될 때까지 <b>멈춤</b></td></tr><tr><td class=\"g-h\"><code>No changes.</code></td><td>설계도와 실제가 같다 → 손수정이 없었다는 증거</td></tr></table></div></section><section class=\"g-topic\"><h4>1.3 언제 쓰고 언제 안 쓰나</h4><div class=\"g-tw\"><table><tr><th>상황</th><th>판단</th><th>이유</th></tr><tr><td class=\"g-h\">dev·prod를 똑같이 만들어야 함</td><td>쓴다</td><td>설계도 하나로 같은 구조를 찍어 냄</td></tr><tr><td class=\"g-h\">권한·예약 작업이 늘어 현황 파악이 어려움</td><td>쓴다</td><td>현황이 파일에 있어 콘솔을 눌러 볼 필요가 없음</td></tr><tr><td class=\"g-h\">한 번 띄우고 버릴 실험 서버</td><td>안 써도 됨</td><td>콘솔 클릭이 더 빠름</td></tr><tr><td class=\"g-h\">매일 바뀌는 앱 코드 배포</td><td>다른 도구</td><td>CI/CD 몫이다. 테라폼은 자원의 그릇을 다룬다</td></tr></table></div><div class=\"g-trap\"><b class=\"g-l\">흔한 오해</b>테라폼은 <b>앱이 잘 도는지</b>는 보지 않는다. 「그릇(서버·권한·예약 작업)이 설계대로 있는가」만 보장한다. 앱 오류와 네트워크 장애는 모니터링의 몫이다.</div></section><section class=\"g-topic\"><h4>1.4 확인 문제</h4><details class=\"g-qa\"><summary>테라폼의 핵심이 코드가 아니라 plan이라고 하는 이유는?</summary><div>바꾸기 전에 무엇이 바뀌는지 보고 사람이 승인·거절할 수 있기 때문이다.</div></details><details class=\"g-qa\"><summary>plan에 「1 to destroy」가 보이면 먼저 무엇을 하나?</summary><div>멈추고 어떤 자원이 왜 지워지는지 확인한다. 이유가 설명되지 않으면 apply하지 않는다.</div></details></section><section class=\"g-topic\"><h4>1.5 다루지 않는 것</h4><ul><li>Terraform Cloud·Enterprise 기능 <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li><li>OpenTofu·Pulumi 등 대안 비교 <span class=\"g-badge g-b-danger\">상황에 따라 다름</span></li></ul></section></div>"}, {"id": "concepts", "title": "핵심 개념", "sub": "2장", "part": "핵심 원리", "html": "<div class=\"g-chapter\" id=\"g-tf-concepts\"><h3><span class=\"g-cn\">02</span>핵심 개념 — 설계도·장부·실제</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>테라폼은 세 곳을 다룬다: 사람이 쓴 <b>설계도</b>(원하는 상태), 도구가 기억하는 <b>장부(state)</b>(내가 아는 상태), 클라우드의 <b>실제</b>(진짜 상태). plan은 이 셋을 비교한다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>셋이 어긋나도 알아채지 못하고, 어긋난 채 적용하면 의도하지 않은 변경이 일어난다.</div><section class=\"g-topic\"><h4>2.1 동작 원리</h4><figure><svg viewBox=\"0 0 720 200\" role=\"img\" aria-label=\"설계도·장부·실제의 관계\"><rect x=\"10\" y=\"50\" width=\"200\" height=\"80\" rx=\"8\" class=\"g-fas\"/><text x=\"110\" y=\"86\" text-anchor=\"middle\" class=\"g-t\">설계도(.tf)</text><text x=\"110\" y=\"104\" text-anchor=\"middle\" class=\"g-ts2\">원하는 상태</text><rect x=\"260\" y=\"50\" width=\"200\" height=\"80\" rx=\"8\" class=\"g-fw\"/><text x=\"360\" y=\"86\" text-anchor=\"middle\" class=\"g-t\">state</text><text x=\"360\" y=\"104\" text-anchor=\"middle\" class=\"g-ts2\">장부: 내가 아는 상태</text><rect x=\"510\" y=\"50\" width=\"200\" height=\"80\" rx=\"8\" class=\"g-fo\"/><text x=\"610\" y=\"86\" text-anchor=\"middle\" class=\"g-t\">실제 클라우드</text><text x=\"610\" y=\"104\" text-anchor=\"middle\" class=\"g-ts2\">진짜 상태</text><path d=\"M212,90 L258,90\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><path d=\"M462,90 L508,90\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><text x=\"235\" y=\"150\" text-anchor=\"middle\" class=\"g-ts2\">plan</text><text x=\"485\" y=\"150\" text-anchor=\"middle\" class=\"g-ts2\">refresh</text><text x=\"360\" y=\"184\" text-anchor=\"middle\" class=\"g-ts2\">plan = 세 곳을 비교해서 「앞으로 바뀔 것」을 계산</text></svg><figcaption><b>그림 2-1</b> 세 곳이 모두 같으면 plan은 「No changes」다</figcaption></figure><div class=\"g-tw\"><table><tr><th>용어</th><th>집 짓기로 치면</th><th>실제 뜻</th></tr><tr><td class=\"g-h\">provider</td><td>건설 회사</td><td>어느 클라우드와 이야기할지(예: Google Cloud)</td></tr><tr><td class=\"g-h\">resource</td><td>방 하나, 창문 하나</td><td>만들 자원 하나(서버·버킷·예약 작업·권한)</td></tr><tr><td class=\"g-h\">data source</td><td>주변 지도 보기</td><td>이미 있는 정보를 읽기만 함</td></tr><tr><td class=\"g-h\">variable / output</td><td>주문서 빈칸 / 완공 보고</td><td>입력 값 / 결과 값</td></tr><tr><td class=\"g-h\">module</td><td>조립식 부품</td><td>자주 쓰는 묶음을 재사용</td></tr><tr><td class=\"g-h\">state</td><td>준공 도면 보관함</td><td>지금 실제로 만든 것의 기록</td></tr><tr><td class=\"g-h\">plan / apply</td><td>견적서 / 실제 공사</td><td>미리보기 / 실제 반영</td></tr></table></div></section><section class=\"g-topic\"><h4>2.2 숫자 예시 — 예약 작업 하나의 변경</h4><p>멈춰 있던 예약 작업을 다시 켜는 변경이다(<code>paused = true</code> → <code>false</code>).</p><div class=\"g-tw\"><table><tr><th>단계</th><th>설계도</th><th>장부</th><th>실제 클라우드</th></tr><tr><td class=\"g-h\">① 시작</td><td>paused = true</td><td>paused = true</td><td>paused = true</td></tr><tr><td class=\"g-h\">② 설계도 수정</td><td><b>paused = false</b></td><td>paused = true</td><td>paused = true</td></tr><tr><td class=\"g-h\">③ plan</td><td>paused = false</td><td>paused = true</td><td>(비교만 함) <code>~ paused: true → false</code></td></tr><tr><td class=\"g-h\">④ apply</td><td>paused = false</td><td><b>false</b>로 갱신</td><td><b>false</b>로 변경</td></tr><tr><td class=\"g-h\">⑤ 다음 plan</td><td>paused = false</td><td>paused = false</td><td><code>No changes.</code> — 셋이 같다</td></tr></table></div></section><section class=\"g-topic\"><h4>2.3 단계 카드</h4><details class=\"g-stage\"><summary><span class=\"g-stage-t\">init</span><span class=\"g-stage-s\">도구와 프로바이더를 내려받는다</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>설계도의 provider·backend 선언</td></tr><tr><td class=\"g-h\">출력</td><td>.terraform 폴더, 잠금 파일(.terraform.lock.hcl)</td></tr><tr><td class=\"g-h\">담당</td><td>작업자(처음 한 번, 버전 바꿀 때)</td></tr><tr><td class=\"g-h\">실패하면</td><td>버전이 고정되지 않으면 어느 날 갑자기 동작이 바뀐다 → 5장 버전 고정</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">plan</span><span class=\"g-stage-s\">바뀔 것을 계산해 보여 준다</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>설계도 + 장부 + 실제(refresh)</td></tr><tr><td class=\"g-h\">출력</td><td>생성·수정·삭제 목록과 요약 줄</td></tr><tr><td class=\"g-h\">담당</td><td>작업자와 리뷰어</td></tr><tr><td class=\"g-h\">실패하면</td><td>plan을 안 읽고 apply하면 안전장치가 없다 → 3장</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">apply</span><span class=\"g-stage-s\">승인된 변경만 실제로 반영</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>저장해 둔 plan 파일(또는 방금의 plan)</td></tr><tr><td class=\"g-h\">출력</td><td>실제 자원 변경 + 장부 갱신</td></tr><tr><td class=\"g-h\">담당</td><td>승인한 사람</td></tr><tr><td class=\"g-h\">실패하면</td><td>중간에 실패하면 일부만 적용된 상태가 된다 → 다시 plan으로 현재 차이를 확인</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>2.4 확인 문제</h4><details class=\"g-qa\"><summary>plan이 「No changes」면 무슨 뜻인가?</summary><div>설계도·장부·실제가 같다. 즉 누군가 콘솔에서 몰래 바꾸지 않았다는 증거다.</div></details><details class=\"g-qa\"><summary>장부가 필요한 이유는?</summary><div>「내가 만든 것이 무엇이고 그 실제 값이 무엇인지」를 기억해야 plan이 바뀔 것만 계산할 수 있다.</div></details></section><section class=\"g-topic\"><h4>2.5 다루지 않는 것</h4><ul><li>HCL 문법 전체(함수·반복) <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li><li>모듈 설계 패턴 <span class=\"g-badge g-b-warn\">개념만 다룸</span></li></ul></section></div>"}, {"id": "plan", "title": "plan 읽는 법", "sub": "3장", "part": "핵심 원리", "html": "<div class=\"g-chapter\" id=\"g-tf-plan\"><h3><span class=\"g-cn\">03</span>plan 읽는 법 — 승인과 거절의 기준</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>plan은 설계도·장부·실제를 비교해, 아무것도 바꾸지 않은 채 앞으로 바뀔 것을 생성(+)·수정(~)·삭제(-)·교체(-/+) 목록으로 보여 주는 실행 전 미리보기다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>미리 읽지 않고 적용하면 지울 줄 몰랐던 것이 지워진다. 특히 「교체」는 이름은 같지만 지우고 새로 만드는 일이라 데이터가 사라질 수 있다.</div><section class=\"g-topic\"><h4>3.1 동작 원리 — 기호 <span class=\"g-badge g-b-fill\">심화</span></h4><p class=\"g-small\">plan 출력 예시(학습용)</p><pre><code> 1    # google_cloud_scheduler_job.ri_sheet_sync will be updated in-place\n 2    ~ resource \"google_cloud_scheduler_job\" \"ri_sheet_sync\" {\n 3        ~ paused = true -&gt; false\n 4      }\n 5  \n 6    # google_project_iam_member.monitor will be created\n 7    + resource \"google_project_iam_member\" \"monitor\" {\n 8        + role   = \"roles/bigquery.metadataViewer\"\n 9      }\n10  \n11    # google_storage_bucket.raw_archive must be replaced\n12  -/+ resource \"google_storage_bucket\" \"raw_archive\" {\n13        ~ location = \"ASIA\" -&gt; \"ASIA-NORTHEAST3\" # forces replacement\n14      }\n15  \n16  Plan: 2 to add, 1 to change, 1 to destroy.</code></pre><div class=\"g-tw\"><table><tr><th>줄</th><th>이 줄이 하는 일</th></tr><tr><td class=\"g-h\">1–4</td><td><b>~</b> 그 자리에서 수정. 멈춰 있던 작업이 다시 켜진다(true → false)</td></tr><tr><td class=\"g-h\">6–9</td><td><b>+</b> 새로 생성. 권한 하나가 추가된다</td></tr><tr><td class=\"g-h\">11–14</td><td><b>-/+</b> <b>교체</b>. 위치(location)는 바꿀 수 없는 값이라 지우고 다시 만든다. 버킷 안 데이터가 지워질 수 있다</td></tr><tr><td class=\"g-h\">16</td><td>요약 줄. 교체는 「1 to destroy」와 「1 to add」에 모두 센다</td></tr></table></div></section><section class=\"g-topic\"><h4>3.2 승인·거절 판정표</h4><div class=\"g-tw\"><table><tr><th>plan에서 본 것</th><th>판단</th><th>이유·다음 행동</th></tr><tr><td class=\"g-h\">destroy 0, 예상한 변경만</td><td>승인 가능</td><td>요약 줄 숫자와 자신의 의도가 일치하는지만 확인</td></tr><tr><td class=\"g-h\"><code>-/+</code> 교체가 있음</td><td>멈춤</td><td><b>forces replacement</b> 표시를 찾아 어떤 인자 때문인지 확인. 데이터가 있으면 백업·이전 계획 필요</td></tr><tr><td class=\"g-h\">내가 안 건드린 자원에 변경</td><td>멈춤</td><td>손수정(drift) 의심 → 4장</td></tr><tr><td class=\"g-h\">변경이 예상보다 훨씬 많음</td><td>멈춤</td><td>잘못된 장부·환경·브랜치를 보고 있는지 확인</td></tr></table></div></section><section class=\"g-topic\"><h4>3.3 단계 카드 — plan을 읽는 순서</h4><details class=\"g-stage\" open><summary><span class=\"g-stage-t\">① 요약 줄</span><span class=\"g-stage-s\">마지막 줄의 세 숫자부터</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>plan 출력 전체</td></tr><tr><td class=\"g-h\">출력</td><td>「지울 것이 있는가」 한 가지 판단</td></tr><tr><td class=\"g-h\">담당</td><td>작업자</td></tr><tr><td class=\"g-h\">실패하면</td><td>긴 출력을 처음부터 읽다가 핵심을 놓친다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② destroy·replace 찾기</span><span class=\"g-stage-s\">-, -/+ 로 시작하는 블록</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>기호가 붙은 블록</td></tr><tr><td class=\"g-h\">출력</td><td>지워질 자원 목록</td></tr><tr><td class=\"g-h\">담당</td><td>작업자 + 리뷰어</td></tr><tr><td class=\"g-h\">실패하면</td><td>이름이 같아 「수정」으로 착각 — 교체 표시를 반드시 확인</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ 원인 찾기</span><span class=\"g-stage-s\">forces replacement 가 붙은 인자</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>교체 블록의 인자 변경</td></tr><tr><td class=\"g-h\">출력</td><td>「이 값은 바꿀 수 없어서 지운다」는 이해</td></tr><tr><td class=\"g-h\">담당</td><td>작업자</td></tr><tr><td class=\"g-h\">실패하면</td><td>원인 없이 apply하면 데이터 손실</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">④ 예상 밖 변경</span><span class=\"g-stage-s\">내가 안 바꾼 곳의 변경</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>수정(~) 블록</td></tr><tr><td class=\"g-h\">출력</td><td>손수정이 있었다는 발견</td></tr><tr><td class=\"g-h\">담당</td><td>팀</td></tr><tr><td class=\"g-h\">실패하면</td><td>그냥 apply하면 남이 한 변경을 덮어쓴다</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>3.4 실패 케이스</h4><div class=\"g-tw\"><table><tr><th>증상</th><th>원인</th><th>막는 법</th></tr><tr><td class=\"g-h\">이름만 바꿨는데 삭제+생성</td><td>리소스 이름이 장부의 키라서</td><td><code>moved</code> 블록으로 이름 변경을 알린다</td></tr><tr><td class=\"g-h\">plan 때와 apply 때가 달라짐</td><td>그 사이 누군가 바꿈</td><td><code>plan -out=tfplan</code> → <code>apply tfplan</code></td></tr><tr><td class=\"g-h\">자동화가 변경 여부를 모름</td><td>출력 문구 파싱</td><td><code>-detailed-exitcode</code>: 0 변경 없음 · 2 변경 있음 · 1 오류</td></tr></table></div></section><section class=\"g-topic\"><h4>3.5 확인 문제</h4><details class=\"g-qa\"><summary>-/+ 는 왜 위험한가?</summary><div>이름은 같지만 지우고 새로 만든다. 저장소·DB처럼 데이터가 든 자원이면 데이터가 사라질 수 있다.</div></details><details class=\"g-qa\"><summary>내가 안 건드린 자원이 수정으로 나오면?</summary><div>누군가 콘솔에서 바꾼 것(drift)일 수 있다. 승인 전에 누가 왜 바꿨는지 확인한다.</div></details></section><section class=\"g-topic\"><h4>3.6 다루지 않는 것</h4><ul><li>plan을 PR에 자동 첨부하는 CI 구성 <span class=\"g-badge g-b-warn\">개념만 다룸</span></li><li>정책 검사(Sentinel/OPA) <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li></ul></section></div>"}, {"id": "state", "title": "장부와 손수정", "sub": "4장", "part": "핵심 원리", "html": "<div class=\"g-chapter\" id=\"g-tf-state\"><h3><span class=\"g-cn\">04</span>장부(state)와 손수정(drift)</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>state는 테라폼이 「내가 만든 것이 무엇이고 실제 값이 무엇인지」 적어 둔 장부 파일이고, drift는 장부·설계도와 실제 클라우드가 달라진 상태다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>장부가 내 컴퓨터에만 있거나 사람마다 다르면 같은 설계도로 서로 다른 것을 만들고, 두 명이 동시에 적용하면 서로 덮어쓴다.</div><section class=\"g-topic\"><h4>4.1 장부는 공유 위치에 <span class=\"g-badge g-b-fill\">심화</span></h4><p class=\"g-small\">장부 설정</p><pre><code> 1  terraform {\n 2    required_version = \"&gt;= 1.5\"\n 3    backend \"gcs\" {\n 4      bucket = \"my-company-tfstate\"\n 5      prefix = \"collect\"\n 6    }\n 7  }</code></pre><div class=\"g-tw\"><table><tr><th>줄</th><th>이 줄이 하는 일</th></tr><tr><td class=\"g-h\">2</td><td>도구 버전 하한을 고정한다</td></tr><tr><td class=\"g-h\">3</td><td><b>backend \"gcs\"</b> — 장부를 내 컴퓨터가 아니라 클라우드 버킷에 둔다. 이 백엔드는 동시 적용을 막는 잠금을 지원한다</td></tr><tr><td class=\"g-h\">4–5</td><td>버킷 이름과 폴더 구분(prefix). 이름은 예시</td></tr></table></div></section><section class=\"g-topic\"><h4>4.2 단계 카드 — 손수정이 적발되는 과정</h4><details class=\"g-stage\" open><summary><span class=\"g-stage-t\">① 누군가 콘솔에서 바꿈</span><span class=\"g-stage-s\">예: 예약 작업을 멈춤</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>콘솔 클릭</td></tr><tr><td class=\"g-h\">출력</td><td>실제만 바뀜(설계도·장부는 그대로)</td></tr><tr><td class=\"g-h\">담당</td><td>누군가</td></tr><tr><td class=\"g-h\">실패하면</td><td>아무 기록도 안 남아 아무도 모른다 — 이게 문제의 시작</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② 다음 plan이 적발</span><span class=\"g-stage-s\">refresh 로 실제를 읽어 차이를 계산</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>설계도·장부·실제</td></tr><tr><td class=\"g-h\">출력</td><td><code>~ paused: false → true</code> 같은 예상 밖 변경</td></tr><tr><td class=\"g-h\">담당</td><td>정기 plan(자동) 또는 다음 작업자</td></tr><tr><td class=\"g-h\">실패하면</td><td>plan을 안 돌리면 영영 모른다 → 주기적 plan 권장</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ 방향 결정</span><span class=\"g-stage-s\">설계도를 현실에 맞출까, 현실을 설계도에 맞출까</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>차이와 변경 사유</td></tr><tr><td class=\"g-h\">출력</td><td>A) 설계도를 고쳐 현실을 인정 / B) apply로 현실을 되돌림</td></tr><tr><td class=\"g-h\">담당</td><td>변경한 사람 + 소유자</td></tr><tr><td class=\"g-h\">실패하면</td><td>사유를 묻지 않고 B를 하면 남의 정당한 긴급 수정을 지운다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">④ 약속 세우기</span><span class=\"g-stage-s\">「콘솔에서 직접 고치지 않는다」</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>팀 합의</td></tr><tr><td class=\"g-h\">출력</td><td>긴급 수정 절차(수정 후 24시간 안에 설계도 반영 등)</td></tr><tr><td class=\"g-h\">담당</td><td>팀 리더</td></tr><tr><td class=\"g-h\">실패하면</td><td>약속이 없으면 설계도가 현실과 달라져 거짓말이 된다</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>4.3 실패 케이스</h4><div class=\"g-tw\"><table><tr><th>증상</th><th>원인</th><th>막는 법</th></tr><tr><td class=\"g-h\">장부를 잃어버림</td><td>로컬 파일에만 있었음</td><td>원격 백엔드 + 버킷 버전 관리</td></tr><tr><td class=\"g-h\">두 사람이 동시에 apply</td><td>잠금 없음</td><td>잠금 지원 백엔드를 쓰고, 잠금이 걸리면 기다린다</td></tr><tr><td class=\"g-h\">장부에 비밀번호가 보임</td><td>장부는 값을 평문으로 담을 수 있음</td><td>버킷 접근을 최소 인원으로, 비밀은 비밀 저장소 참조</td></tr><tr><td class=\"g-h\">장부를 손으로 편집</td><td>급해서 파일을 직접 수정</td><td><code>terraform state</code> 명령만 쓴다</td></tr><tr><td class=\"g-h\">환경끼리 장부를 공유</td><td>prefix 를 구분하지 않음</td><td>환경마다 prefix 또는 별도 버킷</td></tr></table></div></section><section class=\"g-topic\"><h4>4.4 확인 문제</h4><details class=\"g-qa\"><summary>drift는 어떻게 발견하나?</summary><div>plan이 실제를 새로 읽어(refresh) 설계도·장부와 비교해, 내가 안 바꾼 곳의 변경으로 보여 준다.</div></details><details class=\"g-qa\"><summary>장부에 비밀이 들어갈 수 있다는 것의 실무 의미는?</summary><div>장부 버킷의 접근 권한이 곧 비밀의 접근 권한이다. 최소 인원에게만 주고 접근 기록을 남긴다.</div></details></section><section class=\"g-topic\"><h4>4.5 다루지 않는 것</h4><ul><li>workspace·장부 이관 절차 <span class=\"g-badge g-b-warn\">개념만 다룸</span></li><li>장부 암호화 키 관리 <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li></ul></section></div>"}, {"id": "safety", "title": "안전장치", "sub": "5장", "part": "핵심 원리", "html": "<div class=\"g-chapter\" id=\"g-tf-safety\"><h3><span class=\"g-cn\">05</span>안전장치 — 실수가 일어나기 전에 막기</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>안전장치는 실수로 지우거나 과한 권한을 주는 일을 코드 단계에서 막는 설정들이다: 지우기 방지(prevent_destroy), 최소 권한, 버전 고정, 환경 분리, 기존 자원 흡수(import).</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>사람의 주의만으로는 「삭제가 든 plan을 눌러 승인하는」 실수를 막지 못한다.</div><section class=\"g-topic\"><h4>5.1 코드 <span class=\"g-badge g-b-fill\">심화</span></h4><p class=\"g-small\">학습용 예시(이름은 가짜)</p><pre><code> 1  terraform {\n 2    required_providers {\n 3      google = { source = \"hashicorp/google\", version = \"~&gt; 6.0\" }\n 4    }\n 5  }\n 6  \n 7  resource \"google_project_iam_member\" \"monitor\" {\n 8    project = \"my-project\"\n 9    role    = \"roles/bigquery.metadataViewer\"\n10    member  = \"serviceAccount:monitor@my-project.iam.gserviceaccount.com\"\n11  }\n12  \n13  resource \"google_storage_bucket\" \"raw_archive\" {\n14    name     = \"my-company-raw-archive\"\n15    location = \"ASIA-NORTHEAST3\"\n16    lifecycle {\n17      prevent_destroy = true\n18    }\n19  }\n20  \n21  import {\n22    to = google_cloud_scheduler_job.ri_sheet_sync\n23    id = \"projects/my-project/locations/asia-northeast3/jobs/ri-sheet-sync\"\n24  }</code></pre><div class=\"g-tw\"><table><tr><th>줄</th><th>이 줄이 하는 일</th></tr><tr><td class=\"g-h\">2–4</td><td><b>버전 고정</b> — 도구가 어느 날 갑자기 달라지는 것을 막는다(~> 6.0 은 6.x 허용)</td></tr><tr><td class=\"g-h\">7–11</td><td><b>권한 한 줄</b> — 필요한 읽기 권한(metadataViewer)만 준다. 넓은 role(editor/owner)을 피한다(최소 권한)</td></tr><tr><td class=\"g-h\">13–19</td><td><b>prevent_destroy = true</b> — 이 버킷을 지우는 plan은 테라폼이 거부한다. 원본 보관소 같은 곳에 쓴다</td></tr><tr><td class=\"g-h\">21–24</td><td><b>import</b> — 이미 콘솔로 만든 예약 작업을 설계도로 흡수한다(Terraform 1.5+)</td></tr></table></div></section><section class=\"g-topic\"><h4>5.2 권한 리소스 세 가지</h4><div class=\"g-tw\"><table><tr><th>리소스</th><th>동작</th><th>위험</th></tr><tr><td class=\"g-h\"><code>_member</code></td><td>권한 한 사람분만 <b>추가</b></td><td>낮음. 처음엔 이것</td></tr><tr><td class=\"g-h\"><code>_binding</code></td><td>한 역할의 구성원 목록 <b>전체를 덮어씀</b></td><td>목록에 없던 사람의 권한이 사라짐</td></tr><tr><td class=\"g-h\"><code>_policy</code></td><td>프로젝트 권한 <b>전체를 덮어씀</b></td><td>잘못 쓰면 자기 자신도 잠김</td></tr></table></div></section><section class=\"g-topic\"><h4>5.3 단계 카드 — 기존 자원 흡수(import)</h4><details class=\"g-stage\"><summary><span class=\"g-stage-t\">① 대상 파악</span><span class=\"g-stage-s\">콘솔에 있는 자원의 ID를 확인</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>콘솔·명령행으로 본 자원 정보</td></tr><tr><td class=\"g-h\">출력</td><td>import 에 쓸 ID 문자열</td></tr><tr><td class=\"g-h\">담당</td><td>작업자</td></tr><tr><td class=\"g-h\">실패하면</td><td>ID 형식이 자원마다 달라 틀리기 쉽다 → 공식 문서의 import 절을 본다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② import 블록 + 설계도 작성</span><span class=\"g-stage-s\">흡수할 자원과 같은 값으로 쓴다</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>① 의 ID</td></tr><tr><td class=\"g-h\">출력</td><td>import 블록 + resource 블록</td></tr><tr><td class=\"g-h\">담당</td><td>작업자</td></tr><tr><td class=\"g-h\">실패하면</td><td>값이 다르면 흡수 직후 plan에 변경이 뜬다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ plan이 0 변경이 될 때까지</span><span class=\"g-stage-s\">차이가 나면 설계도를 현실에 맞춘다</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>plan 결과의 차이</td></tr><tr><td class=\"g-h\">출력</td><td><code>No changes.</code></td></tr><tr><td class=\"g-h\">담당</td><td>작업자 + 리뷰어</td></tr><tr><td class=\"g-h\">실패하면</td><td>차이를 apply로 「고치면」 실제 운영 값이 바뀐다 — 흡수 단계에서는 설계도를 고친다</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>5.4 실패 케이스</h4><div class=\"g-tw\"><table><tr><th>증상</th><th>원인</th><th>막는 법</th></tr><tr><td class=\"g-h\">권한이 갑자기 사라짐</td><td><code>_binding</code>/_policy 로 덮어씀</td><td><code>_member</code> 사용, plan에서 삭제된 구성원 확인</td></tr><tr><td class=\"g-h\">apply 때 버킷 삭제가 거부됨</td><td>prevent_destroy 가 작동(의도된 보호)</td><td>정말 지울 때만 설정을 풀고 리뷰를 거친다</td></tr><tr><td class=\"g-h\">도구를 올렸더니 plan이 달라짐</td><td>버전 고정을 안 함</td><td>required_providers 와 .terraform.lock.hcl 을 함께 저장소에</td></tr><tr><td class=\"g-h\">운영에서 개발 값이 적용됨</td><td>환경 구분이 없음</td><td>환경별 변수 파일·장부 prefix·계정 분리</td></tr></table></div></section><section class=\"g-topic\"><h4>5.5 확인 문제</h4><details class=\"g-qa\"><summary>prevent_destroy 를 둔 자원을 정말 지워야 하면?</summary><div>설정을 일시적으로 풀고 plan을 리뷰한 뒤 지운다. 보호가 성가신 것이 아니라 한 번 더 멈춰 생각하게 만드는 장치다.</div></details><details class=\"g-qa\"><summary>import 직후 plan에 변경이 보이면?</summary><div>설계도 값이 실제와 다르다는 뜻이다. apply하지 말고 설계도를 현실에 맞춘다.</div></details></section><section class=\"g-topic\"><h4>5.6 다루지 않는 것</h4><ul><li>조직 정책(Organization Policy) <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li><li>서비스 계정 키 관리 <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li></ul></section></div>"}, {"id": "adopt", "title": "도입 순서", "sub": "6장", "part": "운영", "html": "<div class=\"g-chapter\" id=\"g-tf-adopt\"><h3><span class=\"g-cn\">06</span>도입 순서 — 한꺼번에 말고 위험한 것부터</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>도입은 모든 것을 한 번에 바꾸는 것이 아니라 「위험이 큰 것부터 설계도로 옮기고, 옮긴 것은 콘솔 수정을 금지」하는 순차 절차다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>반쯤 옮기면 설계도가 현실과 달라 거짓말이 되고, 오히려 콘솔만 쓸 때보다 헷갈린다.</div><section class=\"g-topic\"><h4>6.1 무엇을 설계도로 둘까</h4><div class=\"g-tw\"><table><tr><th>종류</th><th>판단</th><th>이유</th></tr><tr><td class=\"g-h\">권한(IAM)</td><td>먼저 옮김</td><td>조용히 어긋나면 피해가 크고, 변경 기록이 가장 필요함</td></tr><tr><td class=\"g-h\">예약 작업·스케줄</td><td>먼저 옮김</td><td>멈춘 작업이 어디에도 안 적혀 있기 쉬움</td></tr><tr><td class=\"g-h\">네트워크·방화벽</td><td>옮김</td><td>실수의 영향 범위가 넓음</td></tr><tr><td class=\"g-h\">데이터 저장소</td><td>옮기되 prevent_destroy</td><td>지우면 복구 불가</td></tr><tr><td class=\"g-h\">일회성 실험</td><td>두지 않음</td><td>수명이 짧아 설계도가 곧 낡음</td></tr><tr><td class=\"g-h\">자주 바뀌는 앱 배포</td><td>다른 도구</td><td>CI/CD 영역</td></tr></table></div></section><section class=\"g-topic\"><h4>6.2 단계 카드 — 도입 순서</h4><details class=\"g-stage\" open><summary><span class=\"g-stage-t\">① 범위 정하기</span><span class=\"g-stage-s\">이번에 옮길 자원 10~15개</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>6.1 판단표, 현재 자원 목록</td></tr><tr><td class=\"g-h\">출력</td><td>옮길 목록(소유자 포함)</td></tr><tr><td class=\"g-h\">담당</td><td>팀 리더</td></tr><tr><td class=\"g-h\">실패하면</td><td>범위가 크면 흡수 단계에서 지친다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② 장부 만들기</span><span class=\"g-stage-s\">원격 백엔드와 접근 권한</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>4.1의 설정</td></tr><tr><td class=\"g-h\">출력</td><td>공유 장부와 최소 접근 인원</td></tr><tr><td class=\"g-h\">담당</td><td>플랫폼 담당</td></tr><tr><td class=\"g-h\">실패하면</td><td>장부가 로컬이면 팀 도입이 시작도 못 한다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ 흡수(import)</span><span class=\"g-stage-s\">자원마다 5.3 절차를 반복</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>옮길 목록</td></tr><tr><td class=\"g-h\">출력</td><td>plan 결과 No changes</td></tr><tr><td class=\"g-h\">담당</td><td>작업자</td></tr><tr><td class=\"g-h\">실패하면</td><td>가장 지저분하고 시간이 드는 구간. 하루 분량을 정해 쪼갠다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">④ 자동 plan</span><span class=\"g-stage-s\">PR마다 plan을 돌려 결과를 보여 줌</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>설계도 변경 PR</td></tr><tr><td class=\"g-h\">출력</td><td>리뷰어가 읽을 plan</td></tr><tr><td class=\"g-h\">담당</td><td>CI</td></tr><tr><td class=\"g-h\">실패하면</td><td>자동 apply 는 마지막에. 먼저 plan만 자동화한다</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">⑤ 약속 선언</span><span class=\"g-stage-s\">옮긴 자원은 콘솔 수정 금지</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">입력</td><td>4.2 ④ 의 긴급 수정 절차</td></tr><tr><td class=\"g-h\">출력</td><td>팀 문서와 주기적 plan 점검</td></tr><tr><td class=\"g-h\">담당</td><td>팀 전원</td></tr><tr><td class=\"g-h\">실패하면</td><td>약속이 깨지면 설계도는 곧 현실과 달라진다</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>6.3 반증 — 테라폼이 있어도 못 막는 것</h4><div class=\"g-trap\"><b class=\"g-l\">범위의 한계</b>앱이 500 오류를 내는 것, 네트워크 연결이 끊기는 것, 설계도에 쓰지 않은 자원의 변경은 테라폼으로 막지 못한다. 테라폼은 「장애가 사라지는 도구」가 아니라 「그릇이 설계대로인지 보장하는 도구」다. 앱 상태는 모니터링의 몫이다.</div></section><section class=\"g-topic\"><h4>6.4 확인 문제</h4><details class=\"g-qa\"><summary>왜 권한과 예약 작업부터 옮기나?</summary><div>조용히 어긋나기 쉽고 어긋났을 때 알아차리는 시간이 길어서, 변경 기록의 가치가 가장 크다.</div></details></section><section class=\"g-topic\"><h4>6.5 다루지 않는 것</h4><ul><li>여러 계정·조직에 걸친 대규모 도입 <span class=\"g-badge g-b-danger\">상황에 따라 다름</span></li><li>자동 apply 파이프라인 설계 <span class=\"g-badge g-b-warn\">개념만 다룸</span></li></ul></section></div>"}, {"id": "vibe", "title": "AI에게 시키는 법", "sub": "7장", "part": "심화", "html": "<div class=\"g-chapter\" id=\"g-tf-vibe\"><h3><span class=\"g-cn\">07</span>AI에게 시키는 법 — 아는 말을 넣으면 덜 헤맨다</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>AI는 테라폼 코드를 잘 쓰지만 「건드리면 안 되는 것」은 말해 주지 않으면 모른다. 이 장의 키워드는 AI가 지우고 다시 만드는 코드가 아니라 안전한 변경을 쓰게 만드는 제약이다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>제약을 안 주면 AI는 가장 흔한 예제를 주고, 흔한 예제는 새로 만들거나 넓은 권한을 준다.</div><section class=\"g-topic\"><h4>7.1 키워드 사전</h4><div class=\"g-tw\"><table><tr><th>키워드</th><th>뜻</th><th>넣으면 달라지는 것</th></tr><tr><td class=\"g-h\">terraform plan only, do not apply</td><td>미리보기까지만</td><td>실제 반영을 하지 않음</td></tr><tr><td class=\"g-h\">import existing resources</td><td>이미 있는 것 흡수</td><td>새로 만들다 충돌하는 것을 피함</td></tr><tr><td class=\"g-h\">no destroy / prevent_destroy</td><td>지우기 금지</td><td>지우는 계획을 막음</td></tr><tr><td class=\"g-h\">remote state on GCS backend</td><td>장부를 공유 위치에</td><td>각자 다른 장부로 덮어쓰는 것을 막음</td></tr><tr><td class=\"g-h\">least privilege IAM, use _member only</td><td>최소 권한, 추가형만</td><td>넓은 role·덮어쓰기를 피함</td></tr><tr><td class=\"g-h\">drift detection / plan -refresh-only</td><td>손수정 적발</td><td>콘솔 변경을 찾는 방법을 알려 줌</td></tr><tr><td class=\"g-h\">pin provider version, commit lock file</td><td>도구 버전 고정</td><td>갑작스런 동작 변경을 막음</td></tr><tr><td class=\"g-h\">moved block for rename</td><td>이름 변경 선언</td><td>삭제+생성 대신 이동으로 처리</td></tr></table></div></section><section class=\"g-topic\"><h4>7.2 같은 부탁, 다른 결과</h4><div class=\"g-grid2\"><div class=\"g-trap\"><b class=\"g-l\">헤매는 프롬프트</b><br>테라폼으로 클라우드 스케줄러 만들어줘</div><div class=\"g-key g-okkey\"><b class=\"g-l\">덜 헤매는 프롬프트</b><br>GCP 프로젝트 my-project에 이미 있는 Cloud Scheduler 잡 ri-sheet-sync를 Terraform import 블록으로 흡수하는 코드를 써 줘. google provider 버전 고정, state는 GCS backend. plan만 돌려서 변경이 0인지 확인하는 방법까지. apply·destroy 명령은 쓰지 마.</div></div><p class=\"g-small\">왜 다른가: 「이미 있다」와 「plan만」을 말하니 AI가 새로 만들거나 지우는 계획을 세우지 않는다.</p><div class=\"g-grid2\"><div class=\"g-trap\"><b class=\"g-l\">헤매는 프롬프트</b><br>모니터한테 BigQuery 권한 줘</div><div class=\"g-key g-okkey\"><b class=\"g-l\">덜 헤매는 프롬프트</b><br>monitor 서비스 계정에 BigQuery 메타데이터 읽기만 필요해. google_project_iam_member로 roles/bigquery.metadataViewer 한 줄만 추가하고 더 넓은 role은 쓰지 마. plan 결과에서 무엇을 확인해야 하는지도 알려 줘.</div></div><p class=\"g-small\">왜 다른가: 최소 권한을 정확히 말하면 AI가 습관처럼 넓은 권한(editor)을 주지 않는다.</p></section><section class=\"g-topic\"><h4>7.3 프롬프트 틀</h4><ol><li><b>무엇을</b>: 만들거나 바꿀 자원 한 줄</li><li><b>현재 상태</b>: 이미 있는가(import)? 장부는 어디인가?</li><li><b>금지</b>: apply/destroy 금지, 넓은 권한 금지, 기존 자원 삭제 금지</li><li><b>안전장치</b>: 버전 고정, prevent_destroy 대상</li><li><b>검증</b>: plan 결과에서 무엇을 확인할지(destroy 0, 교체 없음)</li></ol></section><section class=\"g-topic\"><h4>7.4 AI가 준 설계도, 이것만 확인</h4><ul class=\"g-checklist\"><li>plan 마지막 줄에 destroy 가 0인가?</li><li>-/+ (교체)가 없는가?</li><li>권한(role)이 필요한 만큼만인가?</li><li>장부가 공유 버킷(GCS)에 있는가?</li><li>비밀번호·키가 코드에 그대로 없는가?</li><li>apply 는 사람이 plan을 본 뒤에만 하는가?</li></ul><div class=\"g-trap\"><b class=\"g-l\">가장 중요한 규칙</b>AI에게는 기본으로 「plan까지만」 시킨다. 되돌릴 수 없는 apply는 사람이 plan을 읽고 승인한 뒤에 한다.</div></section><section class=\"g-topic\"><h4>7.5 다루지 않는 것</h4><ul><li>특정 AI 도구별 사용법 <span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></li></ul></section></div>"}, {"id": "limits", "title": "다루지 않는 것과 선택 기준", "sub": "8장", "part": "경계", "html": "<div class=\"g-chapter\" id=\"g-tf-limits\"><h3><span class=\"g-cn\">08</span>다루지 않는 것과 선택 기준</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>이 장은 이 책이 의도적으로 다루지 않은 것과, 정답이 상황에 따라 달라지는 선택을 숨기지 않고 모아 둔 목록이다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>경계를 숨기면 「책에 없으니 필요 없다」로 읽혀, 운영에서 가장 먼저 빠뜨릴 것들이 빠진다.</div><section class=\"g-topic\"><h4>8.1 다루지 않는 것</h4><div class=\"g-tw\"><table><tr><th>주제</th><th>상태</th><th>어디서 보나</th></tr><tr><td class=\"g-h\">HCL 문법 전체·함수</td><td><span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></td><td>공식 Language 문서</td></tr><tr><td class=\"g-h\">모듈 설계</td><td><span class=\"g-badge g-b-warn\">개념만 다룸</span></td><td>공식 모듈 가이드</td></tr><tr><td class=\"g-h\">정책 검사·승인 워크플로</td><td><span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></td><td>Sentinel / OPA</td></tr><tr><td class=\"g-h\">Terraform Cloud / 관리형 실행</td><td><span class=\"g-badge g-b-neutral\">이 책에서 다루지 않음</span></td><td>HashiCorp 문서</td></tr></table></div></section><section class=\"g-topic\"><h4>8.2 정해지지 않은 것 — 상황에 따라 다름</h4><div class=\"g-tw\"><table><tr><th>질문</th><th>판단 기준</th></tr><tr><td class=\"g-h\">테라폼 vs OpenTofu vs Pulumi</td><td>팀의 언어 선호, 라이선스, 기존 자산 (<span class=\"g-badge g-b-danger\">상황에 따라 다름</span>)</td></tr><tr><td class=\"g-h\">자동 apply 를 쓸까</td><td>변경 위험도, 승인 절차, 롤백 수단이 갖춰졌을 때만</td></tr><tr><td class=\"g-h\">환경 분리 방식(폴더 vs workspace)</td><td>환경 간 차이의 크기와 팀 규모</td></tr></table></div></section></div>"}, {"id": "ref", "title": "용어 사전·근거·개정 이력", "sub": "9장", "part": "부록", "html": "<div class=\"g-chapter\" id=\"g-tf-ref\"><h3><span class=\"g-cn\">09</span>용어 사전 · 근거 자료 · 개정 이력</h3><div class=\"g-key\"><b class=\"g-l\">정의</b>이 장은 책 전체의 용어를 한·영 병기로 모으고, 기술 사실의 근거와 문서의 변경 이력을 남긴다.</div><div class=\"g-trap\"><b class=\"g-l\">이게 없으면</b>용어가 흩어져 있으면 장마다 다르게 이해하고, 근거가 없으면 틀려도 고칠 곳을 모른다.</div><section class=\"g-topic\"><h4>9.1 용어 사전</h4><div class=\"g-tw\"><table><tr><th>용어</th><th>뜻</th></tr><tr><td class=\"g-h\">설계도</td><td>원하는 상태를 적은 .tf 파일</td></tr><tr><td class=\"g-h\">IaC</td><td>코드로 관리하는 인프라(Infrastructure as Code)</td></tr><tr><td class=\"g-h\">provider</td><td>어느 클라우드와 통신할지 정하는 플러그인</td></tr><tr><td class=\"g-h\">resource</td><td>만들 자원 하나</td></tr><tr><td class=\"g-h\">state</td><td>테라폼이 아는 현재 상태를 적은 장부 파일</td></tr><tr><td class=\"g-h\">plan</td><td>아무것도 바꾸지 않고 바뀔 것을 계산해 보여 주는 미리보기</td></tr><tr><td class=\"g-h\">apply</td><td>승인된 변경을 실제로 반영</td></tr><tr><td class=\"g-h\">drift</td><td>설계도·장부와 실제가 달라진 상태</td></tr><tr><td class=\"g-h\">import</td><td>이미 있는 자원을 설계도·장부로 흡수</td></tr><tr><td class=\"g-h\">replace (-/+)</td><td>지우고 같은 이름으로 다시 만듦</td></tr><tr><td class=\"g-h\">prevent_destroy</td><td>지우는 plan을 거부하는 보호 설정</td></tr><tr><td class=\"g-h\">backend</td><td>장부를 어디에 저장할지 정하는 설정</td></tr><tr><td class=\"g-h\">lock</td><td>동시에 하나만 적용하도록 장부에 거는 잠금</td></tr><tr><td class=\"g-h\">least privilege</td><td>필요한 만큼만 권한을 주는 원칙</td></tr><tr><td class=\"g-h\">module</td><td>자주 쓰는 설계도 묶음을 재사용하는 단위</td></tr></table></div></section><section class=\"g-topic\"><h4>9.2 근거 자료</h4><ol class=\"g-sources\"><li><a href=\"https://developer.hashicorp.com/terraform/intro\">What is Terraform</a> — 개념 소개</li><li><a href=\"https://developer.hashicorp.com/terraform/cli/commands/plan\">terraform plan</a> — 미리보기 읽는 법, -detailed-exitcode</li><li><a href=\"https://developer.hashicorp.com/terraform/language/import\">Import</a> — import 블록(1.5+)</li><li><a href=\"https://developer.hashicorp.com/terraform/language/state\">State</a> — 장부·잠금·민감 값</li><li><a href=\"https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle\">lifecycle</a> — prevent_destroy</li><li><a href=\"https://registry.terraform.io/providers/hashicorp/google/latest/docs/resources/google_project_iam\">google_project_iam</a> — _member / _binding / _policy 차이</li></ol><p>명령·옵션은 버전마다 달라지므로 실습 전에 해당 버전 문서를 확인한다. 장부에 민감 값이 평문으로 들어갈 수 있다는 점은 State 문서를 근거로 한다.</p></section><section class=\"g-topic\"><h4>9.3 첫 실습 제안</h4><ol><li>개인 테스트 프로젝트에서 버킷 하나를 설계도로 만든다(<span class=\"g-badge g-b-ok\">실습으로 확인 가능</span>)</li><li><code>plan</code>으로 미리보기를 읽고 <code>apply</code></li><li>콘솔에서 버킷 라벨을 손으로 바꾼다</li><li>다시 plan 을 돌려 「손수정 적발」을 눈으로 확인한다</li><li>설계도를 현실에 맞춰 No changes 로 되돌린다</li></ol></section><section class=\"g-topic\"><h4>9.4 개정 이력</h4><div class=\"g-tw\"><table><tr><th>버전</th><th>날짜</th><th>내용</th></tr><tr><td class=\"g-h\">v0.2</td><td>2026-10-15</td><td>정의·이유·원리·단계 카드·실패 케이스·다루지 않는 것·사전의 고정 틀로 전면 재작성. 한/영 동시 제공. 사내 사례는 일반 예시로 대체.</td></tr><tr><td class=\"g-h\">v0.1</td><td>2026-10-14</td><td>초판(개념 중심 입문, 한국어)</td></tr></table></div></section></div>"}];
export const sectionsEn = [{"id": "guide", "title": "About This Book", "sub": "Ch. 0", "part": "Start", "html": "<header class=\"g-cover\"><div class=\"g-kicker\">Study guide · Infrastructure</div><h1>Terraform: Blueprints Instead of Clicks</h1><p class=\"g-lead\">Why manage the cloud with files instead of clicks — reading a plan, state and drift, safety rails, adoption steps, and how to instruct an AI — in one consistent frame.</p><div class=\"g-chips\"><span class=\"g-chip\">Plain-language</span><span class=\"g-chip\">Reading plans</span><span class=\"g-chip\">Failure cases</span><span class=\"g-chip\">KO / EN</span></div></header><div class=\"g-chapter\" id=\"g-tf-guide\"><h3><span class=\"g-cn\">00</span>About This Book</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>This book teaches a beginner what Terraform is, why it is needed, and where and how it goes wrong — using the same frame in every chapter.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>If you only memorize commands, you will not recognize what is dangerous when a plan shows a deletion.</div><section class=\"g-topic\"><h4>1.1 Purpose and scope</h4><p>The audience has managed a cloud by clicking in a console. The scope is blueprint → read the plan → apply → manage the ledger → safety rails → adoption. The goal is not memorizing syntax but <b>reading a plan and deciding to approve or reject</b>.</p><p>All examples use made-up names (such as my-project) and relate to no real company resources.</p></section><section class=\"g-topic\"><h4>1.2 How each chapter is laid out</h4><div class=\"g-tw\"><table><tr><th>Part</th><th>What it answers</th></tr><tr><td class=\"g-h\">Definition</td><td>What is it, in one sentence</td></tr><tr><td class=\"g-h\">Without it</td><td>Why we need it</td></tr><tr><td class=\"g-h\">How it works</td><td>A diagram and a worked example</td></tr><tr><td class=\"g-h\">Stage cards</td><td>Input, output, owner, failure — tap to open</td></tr><tr><td class=\"g-h\">Failure cases</td><td>Where and how it breaks</td></tr><tr><td class=\"g-h\">Code and keywords</td><td>Advanced. Words for your AI prompt</td></tr><tr><td class=\"g-h\">Not covered</td><td>We do not hide the edges</td></tr></table></div></section><section class=\"g-topic\"><h4>1.3 Notation and as-of date</h4><div class=\"g-tw\"><table><tr><th>Badge</th><th>Meaning</th></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-ok\">Hands-on</span></td><td>You can try it in a personal sandbox project</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-warn\">Concept only</span></td><td>Concepts and decision criteria only</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-danger\">Depends</span></td><td>Depends on your team and situation</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-neutral\">Not covered</span></td><td>Out of scope</td></tr><tr><td class=\"g-h\"><span class=\"g-badge g-b-fill\">Advanced</span></td><td>Advanced section with code</td></tr></table></div><p>As of 2026-10-15. Commands and options vary by version; re-check the official docs (Ch.9). The <code>import</code> block requires Terraform 1.5 or later.</p></section></div>"}, {"id": "overview", "title": "The Big Picture", "sub": "Ch. 1", "part": "Basics", "html": "<div class=\"g-chapter\" id=\"g-tf-overview\"><h3><span class=\"g-cn\">01</span>The Big Picture — Blueprints Instead of Clicks</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>Terraform lets you write the resources the cloud should contain as files (a blueprint); the tool then makes reality match it — Infrastructure as Code (IaC).</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Click-based changes leave no record, so you cannot recreate an environment or tell who changed what and when. Noticing takes far longer than fixing.</div><section class=\"g-topic\"><h4>1.1 How it works</h4><p>Clicking is assembling LEGO by hand without instructions. The blueprint way writes the instructions first, builds from them, and spots anyone who secretly swaps a brick by comparing against them.</p><figure><svg viewBox=\"0 0 720 296\" role=\"img\" aria-label=\"Click vs. blueprint\"><rect x=\"6\" y=\"6\" width=\"340\" height=\"284\" rx=\"10\" class=\"g-zone\"/><rect x=\"374\" y=\"6\" width=\"340\" height=\"284\" rx=\"10\" class=\"g-zone g-zone2\"/><text x=\"22\" y=\"30\" text-anchor=\"start\" class=\"g-ts2\">Click in the console</text><text x=\"390\" y=\"30\" text-anchor=\"start\" class=\"g-ts2\">Manage with a blueprint</text><rect x=\"24\" y=\"46\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fb\"/><text x=\"176\" y=\"74\" text-anchor=\"middle\" class=\"g-t\">Change by clicking</text><rect x=\"392\" y=\"46\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fas\"/><text x=\"544\" y=\"74\" text-anchor=\"middle\" class=\"g-t\">Edit the blueprint</text><rect x=\"24\" y=\"106\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fb\"/><text x=\"176\" y=\"134\" text-anchor=\"middle\" class=\"g-t\">Applied instantly</text><rect x=\"392\" y=\"106\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fw\"/><text x=\"544\" y=\"134\" text-anchor=\"middle\" class=\"g-t\">plan: list of changes</text><rect x=\"24\" y=\"166\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fh\"/><text x=\"176\" y=\"194\" text-anchor=\"middle\" class=\"g-t\">No record</text><rect x=\"392\" y=\"166\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fb\"/><text x=\"544\" y=\"194\" text-anchor=\"middle\" class=\"g-t\">A person approves</text><rect x=\"24\" y=\"226\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fh\"/><text x=\"176\" y=\"254\" text-anchor=\"middle\" class=\"g-t\">Found days later</text><rect x=\"392\" y=\"226\" width=\"304\" height=\"48\" rx=\"8\" class=\"g-fo\"/><text x=\"544\" y=\"254\" text-anchor=\"middle\" class=\"g-t\">apply; history kept</text></svg><figcaption><b>Figure 1-1</b> The same change, but the blueprint way is previewed, approved, and recorded</figcaption></figure><figure><svg viewBox=\"0 0 720 144\" role=\"img\" aria-label=\"Terraform workflow\"><rect x=\"6\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fas\"/><text x=\"66\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">Edit blueprint</text><text x=\"66\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">.tf</text><path d=\"M129,51 L151,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"153\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fw\"/><text x=\"213\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">plan</text><text x=\"213\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">preview</text><path d=\"M276,51 L298,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"300\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fb\"/><text x=\"360\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">Approve</text><text x=\"360\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">a person</text><path d=\"M422,51 L444,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"446\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fo\"/><text x=\"507\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">apply</text><text x=\"507\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">apply</text><path d=\"M569,51 L591,51\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><rect x=\"593\" y=\"14\" width=\"121\" height=\"74\" rx=\"8\" class=\"g-fo\"/><text x=\"654\" y=\"47\" text-anchor=\"middle\" class=\"g-t\" style=\"font-size:13px\">Cloud</text><text x=\"654\" y=\"65\" text-anchor=\"middle\" class=\"g-ts2\">real resources</text><path d=\"M654,90 C654,132 213,132 213,92\" class=\"g-fla g-fd\" marker-end=\"url(#g-aha)\"/><text x=\"433\" y=\"128\" text-anchor=\"middle\" class=\"g-ts2\">state (ledger): records what really exists → compared at the next plan</text></svg><figcaption><b>Figure 1-2</b> The heart of it is not code but the plan (preview)</figcaption></figure></section><section class=\"g-topic\"><h4>1.2 Worked example — summary of one change</h4><div class=\"g-tw\"><table><tr><th>Last line of plan</th><th>How to read it</th></tr><tr><td class=\"g-h\"><code>Plan: 1 to add, 1 to change, 0 to destroy.</code></td><td>1 new, 1 modified, <b>0 destroyed</b> → generally safe to approve</td></tr><tr><td class=\"g-h\"><code>Plan: 0 to add, 0 to change, 1 to destroy.</code></td><td>Something will be deleted → <b>stop</b> until you know what and why</td></tr><tr><td class=\"g-h\"><code>No changes.</code></td><td>Blueprint equals reality → evidence of no manual edits</td></tr></table></div></section><section class=\"g-topic\"><h4>1.3 When to use it — and when not</h4><div class=\"g-tw\"><table><tr><th>Situation</th><th>Verdict</th><th>Why</th></tr><tr><td class=\"g-h\">dev and prod must match</td><td>Use</td><td>One blueprint stamps identical structure</td></tr><tr><td class=\"g-h\">Permissions and schedules grow and are hard to track</td><td>Use</td><td>Status lives in files; no console hunting</td></tr><tr><td class=\"g-h\">A throwaway experiment server</td><td>Skip</td><td>Console clicks are faster</td></tr><tr><td class=\"g-h\">Daily app code deploys</td><td>Other tooling</td><td>That is CI/CD; Terraform handles the containers</td></tr></table></div><div class=\"g-trap\"><b class=\"g-l\">Common misconception</b>Terraform does not check <b>whether the app works</b>. It only guarantees the containers (servers, permissions, schedules) match the blueprint. App errors and network outages are monitoring’s job.</div></section><section class=\"g-topic\"><h4>1.4 Check yourself</h4><details class=\"g-qa\"><summary>Why is plan, not code, the heart of Terraform?</summary><div>Because you see what will change before it does, and a person can approve or reject.</div></details><details class=\"g-qa\"><summary>What do you do first when plan shows “1 to destroy”?</summary><div>Stop and find out which resource is deleted and why; do not apply until it is explained.</div></details></section><section class=\"g-topic\"><h4>1.5 Not covered</h4><ul><li>Terraform Cloud/Enterprise features <span class=\"g-badge g-b-neutral\">Not covered</span></li><li>Comparison with OpenTofu, Pulumi, etc. <span class=\"g-badge g-b-danger\">Depends</span></li></ul></section></div>"}, {"id": "concepts", "title": "Core Concepts", "sub": "Ch. 2", "part": "Core", "html": "<div class=\"g-chapter\" id=\"g-tf-concepts\"><h3><span class=\"g-cn\">02</span>Core Concepts — Blueprint, Ledger, Reality</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>Terraform deals with three places: the <b>blueprint</b> (desired state) you write, the <b>state ledger</b> (what the tool believes exists), and <b>reality</b> in the cloud. A plan compares the three.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>You will not notice when they diverge, and applying while diverged causes unintended changes.</div><section class=\"g-topic\"><h4>2.1 How it works</h4><figure><svg viewBox=\"0 0 720 200\" role=\"img\" aria-label=\"Blueprint, ledger, reality\"><rect x=\"10\" y=\"50\" width=\"200\" height=\"80\" rx=\"8\" class=\"g-fas\"/><text x=\"110\" y=\"86\" text-anchor=\"middle\" class=\"g-t\">Blueprint (.tf)</text><text x=\"110\" y=\"104\" text-anchor=\"middle\" class=\"g-ts2\">desired state</text><rect x=\"260\" y=\"50\" width=\"200\" height=\"80\" rx=\"8\" class=\"g-fw\"/><text x=\"360\" y=\"86\" text-anchor=\"middle\" class=\"g-t\">state</text><text x=\"360\" y=\"104\" text-anchor=\"middle\" class=\"g-ts2\">ledger: what I believe exists</text><rect x=\"510\" y=\"50\" width=\"200\" height=\"80\" rx=\"8\" class=\"g-fo\"/><text x=\"610\" y=\"86\" text-anchor=\"middle\" class=\"g-t\">Real cloud</text><text x=\"610\" y=\"104\" text-anchor=\"middle\" class=\"g-ts2\">actual state</text><path d=\"M212,90 L258,90\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><path d=\"M462,90 L508,90\" class=\"g-fl\" marker-end=\"url(#g-ah)\"/><text x=\"235\" y=\"150\" text-anchor=\"middle\" class=\"g-ts2\">plan</text><text x=\"485\" y=\"150\" text-anchor=\"middle\" class=\"g-ts2\">refresh</text><text x=\"360\" y=\"184\" text-anchor=\"middle\" class=\"g-ts2\">plan = compare the three and compute what will change</text></svg><figcaption><b>Figure 2-1</b> When all three agree, plan says “No changes”.</figcaption></figure><div class=\"g-tw\"><table><tr><th>Term</th><th>House-building analogy</th><th>Real meaning</th></tr><tr><td class=\"g-h\">provider</td><td>The construction firm</td><td>Which cloud to talk to (e.g., Google Cloud)</td></tr><tr><td class=\"g-h\">resource</td><td>A room, a window</td><td>One resource to create (server, bucket, schedule, permission)</td></tr><tr><td class=\"g-h\">data source</td><td>Reading the surrounding map</td><td>Read-only lookup of what exists</td></tr><tr><td class=\"g-h\">variable / output</td><td>Order form blanks / completion report</td><td>Inputs / result values</td></tr><tr><td class=\"g-h\">module</td><td>A prefab part</td><td>A reusable bundle</td></tr><tr><td class=\"g-h\">state</td><td>The as-built drawings</td><td>A record of what was actually built</td></tr><tr><td class=\"g-h\">plan / apply</td><td>Estimate / actual construction</td><td>Preview / real change</td></tr></table></div></section><section class=\"g-topic\"><h4>2.2 Worked example — changing one scheduled job</h4><p>A change that re-enables a paused scheduled job (<code>paused = true</code> → <code>false</code>).</p><div class=\"g-tw\"><table><tr><th>Step</th><th>Blueprint</th><th>Ledger</th><th>Reality</th></tr><tr><td class=\"g-h\">① Start</td><td>paused = true</td><td>paused = true</td><td>paused = true</td></tr><tr><td class=\"g-h\">② Edit blueprint</td><td><b>paused = false</b></td><td>paused = true</td><td>paused = true</td></tr><tr><td class=\"g-h\">③ plan</td><td>paused = false</td><td>paused = true</td><td>(compare only) <code>~ paused: true → false</code></td></tr><tr><td class=\"g-h\">④ apply</td><td>paused = false</td><td>updated to <b>false</b></td><td>changed to <b>false</b></td></tr><tr><td class=\"g-h\">⑤ Next plan</td><td>paused = false</td><td>paused = false</td><td><code>No changes.</code> — all three agree</td></tr></table></div></section><section class=\"g-topic\"><h4>2.3 Stage cards</h4><details class=\"g-stage\"><summary><span class=\"g-stage-t\">init</span><span class=\"g-stage-s\">Download the tool plugins</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>provider and backend declarations</td></tr><tr><td class=\"g-h\">Output</td><td>.terraform folder and lock file (.terraform.lock.hcl)</td></tr><tr><td class=\"g-h\">Owner</td><td>The operator (once, and on version changes)</td></tr><tr><td class=\"g-h\">If it fails</td><td>Unpinned versions change behavior one day → pin versions (Ch.5)</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">plan</span><span class=\"g-stage-s\">Compute and show what will change</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>Blueprint + ledger + reality (refresh)</td></tr><tr><td class=\"g-h\">Output</td><td>Create/modify/destroy list and a summary line</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator and reviewer</td></tr><tr><td class=\"g-h\">If it fails</td><td>Applying without reading the plan removes the safety net → Ch.3</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">apply</span><span class=\"g-stage-s\">Make only approved changes real</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>A saved plan file (or the fresh plan)</td></tr><tr><td class=\"g-h\">Output</td><td>Real changes + a ledger update</td></tr><tr><td class=\"g-h\">Owner</td><td>The approver</td></tr><tr><td class=\"g-h\">If it fails</td><td>A mid-way failure leaves a partial apply → re-plan to see the remaining diff</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>2.4 Check yourself</h4><details class=\"g-qa\"><summary>What does “No changes” mean?</summary><div>The blueprint, ledger, and reality agree — evidence that nobody secretly changed it in the console.</div></details><details class=\"g-qa\"><summary>Why is the ledger needed?</summary><div>Terraform must remember what it built and its real values to compute only what will change.</div></details></section><section class=\"g-topic\"><h4>2.5 Not covered</h4><ul><li>Full HCL syntax (functions, loops) <span class=\"g-badge g-b-neutral\">Not covered</span></li><li>Module design patterns <span class=\"g-badge g-b-warn\">Concept only</span></li></ul></section></div>"}, {"id": "plan", "title": "Reading a Plan", "sub": "Ch. 3", "part": "Core", "html": "<div class=\"g-chapter\" id=\"g-tf-plan\"><h3><span class=\"g-cn\">03</span>Reading a Plan — Criteria to Approve or Reject</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>A plan compares blueprint, ledger and reality and, without changing anything, lists what will be created (+), modified (~), destroyed (-), or replaced (-/+).</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Without reading it first, you delete things you did not mean to. “Replace” keeps the name but deletes and recreates, which can destroy data.</div><section class=\"g-topic\"><h4>3.1 How it works — symbols <span class=\"g-badge g-b-fill\">Advanced</span></h4><p class=\"g-small\">Example plan output (for learning)</p><pre><code> 1    # google_cloud_scheduler_job.ri_sheet_sync will be updated in-place\n 2    ~ resource \"google_cloud_scheduler_job\" \"ri_sheet_sync\" {\n 3        ~ paused = true -&gt; false\n 4      }\n 5  \n 6    # google_project_iam_member.monitor will be created\n 7    + resource \"google_project_iam_member\" \"monitor\" {\n 8        + role   = \"roles/bigquery.metadataViewer\"\n 9      }\n10  \n11    # google_storage_bucket.raw_archive must be replaced\n12  -/+ resource \"google_storage_bucket\" \"raw_archive\" {\n13        ~ location = \"ASIA\" -&gt; \"ASIA-NORTHEAST3\" # forces replacement\n14      }\n15  \n16  Plan: 2 to add, 1 to change, 1 to destroy.</code></pre><div class=\"g-tw\"><table><tr><th>Line</th><th>What it does</th></tr><tr><td class=\"g-h\">1–4</td><td><b>~</b> modified in place; the paused job turns on again (true → false)</td></tr><tr><td class=\"g-h\">6–9</td><td><b>+</b> created; one permission is added</td></tr><tr><td class=\"g-h\">11–14</td><td><b>-/+</b> <b>replacement</b>. Location cannot be changed in place, so it is deleted and recreated — bucket data may be lost</td></tr><tr><td class=\"g-h\">16</td><td>The summary line. A replacement counts in both “destroy” and “add”</td></tr></table></div></section><section class=\"g-topic\"><h4>3.2 Approve / reject table</h4><div class=\"g-tw\"><table><tr><th>What you see</th><th>Verdict</th><th>Why and next step</th></tr><tr><td class=\"g-h\">destroy 0, only expected changes</td><td>Approve</td><td>Just confirm the numbers match your intent</td></tr><tr><td class=\"g-h\"><code>-/+</code> a replacement</td><td>Stop</td><td>Find the <b>forces replacement</b> marker; if data exists, plan a backup and migration</td></tr><tr><td class=\"g-h\">Changes to resources I did not touch</td><td>Stop</td><td>Suspect drift → Ch.4</td></tr><tr><td class=\"g-h\">Far more changes than expected</td><td>Stop</td><td>Check you are on the right ledger, environment, and branch</td></tr></table></div></section><section class=\"g-topic\"><h4>3.3 Stage cards — the reading order</h4><details class=\"g-stage\" open><summary><span class=\"g-stage-t\">① The summary line</span><span class=\"g-stage-s\">Start with the three numbers on the last line</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The full plan output</td></tr><tr><td class=\"g-h\">Output</td><td>One judgment: is anything deleted?</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator</td></tr><tr><td class=\"g-h\">If it fails</td><td>Reading from the top, you miss the point</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② Find destroy and replace</span><span class=\"g-stage-s\">Blocks starting with - or -/+</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>Symbol-marked blocks</td></tr><tr><td class=\"g-h\">Output</td><td>The list of resources to be deleted</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator + reviewer</td></tr><tr><td class=\"g-h\">If it fails</td><td>Same name looks like a “modify” — always check the replace marker</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ Find the cause</span><span class=\"g-stage-s\">The argument tagged forces replacement</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The argument change in the replace block</td></tr><tr><td class=\"g-h\">Output</td><td>Understanding that the value is immutable</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator</td></tr><tr><td class=\"g-h\">If it fails</td><td>Applying without a cause risks data loss</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">④ Unexpected changes</span><span class=\"g-stage-s\">Changes where I changed nothing</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>Modify (~) blocks</td></tr><tr><td class=\"g-h\">Output</td><td>Discovery that someone edited by hand</td></tr><tr><td class=\"g-h\">Owner</td><td>The team</td></tr><tr><td class=\"g-h\">If it fails</td><td>Applying blindly overwrites someone else’s change</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>3.4 Failure cases</h4><div class=\"g-tw\"><table><tr><th>Symptom</th><th>Cause</th><th>Prevention</th></tr><tr><td class=\"g-h\">Only renamed, got delete+create</td><td>The resource name is the ledger key</td><td><code>moved</code> block to declare the rename</td></tr><tr><td class=\"g-h\">Plan and apply differ</td><td>Someone changed things in between</td><td><code>plan -out=tfplan</code> → <code>apply tfplan</code></td></tr><tr><td class=\"g-h\">Automation cannot tell if there are changes</td><td>Parsing output text</td><td><code>-detailed-exitcode</code>: 0 no changes · 2 changes · 1 error</td></tr></table></div></section><section class=\"g-topic\"><h4>3.5 Check yourself</h4><details class=\"g-qa\"><summary>Why is -/+ dangerous?</summary><div>The name stays but it is deleted and recreated; for storage or databases that can destroy data.</div></details><details class=\"g-qa\"><summary>What if a resource I did not touch shows as modified?</summary><div>Likely drift from a console edit; find out who changed it and why before approving.</div></details></section><section class=\"g-topic\"><h4>3.6 Not covered</h4><ul><li>CI that posts plans to pull requests <span class=\"g-badge g-b-warn\">Concept only</span></li><li>Policy checks (Sentinel/OPA) <span class=\"g-badge g-b-neutral\">Not covered</span></li></ul></section></div>"}, {"id": "state", "title": "State and Drift", "sub": "Ch. 4", "part": "Core", "html": "<div class=\"g-chapter\" id=\"g-tf-state\"><h3><span class=\"g-cn\">04</span>The Ledger (state) and Drift</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>State is the ledger file where Terraform records what it built and the real values; drift is the condition where the ledger and blueprint differ from the actual cloud.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>If the ledger lives only on one laptop or differs per person, the same blueprint builds different things — and two simultaneous applies overwrite each other.</div><section class=\"g-topic\"><h4>4.1 Keep the ledger in a shared place <span class=\"g-badge g-b-fill\">Advanced</span></h4><p class=\"g-small\">Ledger config</p><pre><code> 1  terraform {\n 2    required_version = \"&gt;= 1.5\"\n 3    backend \"gcs\" {\n 4      bucket = \"my-company-tfstate\"\n 5      prefix = \"collect\"\n 6    }\n 7  }</code></pre><div class=\"g-tw\"><table><tr><th>Line</th><th>What it does</th></tr><tr><td class=\"g-h\">2</td><td>Pin a minimum tool version</td></tr><tr><td class=\"g-h\">3</td><td><b>backend \"gcs\"</b> — keep the ledger in a cloud bucket, not on a laptop; this backend supports locking against concurrent applies</td></tr><tr><td class=\"g-h\">4–5</td><td>Bucket name and prefix (example names)</td></tr></table></div></section><section class=\"g-topic\"><h4>4.2 Stage cards — how a manual edit is caught</h4><details class=\"g-stage\" open><summary><span class=\"g-stage-t\">① Someone edits in the console</span><span class=\"g-stage-s\">e.g., pauses a scheduled job</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>A console click</td></tr><tr><td class=\"g-h\">Output</td><td>Reality changes; blueprint and ledger do not</td></tr><tr><td class=\"g-h\">Owner</td><td>Someone</td></tr><tr><td class=\"g-h\">If it fails</td><td>No record is left and nobody knows — this is where trouble starts</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② The next plan catches it</span><span class=\"g-stage-s\">Refresh reads reality and computes the diff</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>Blueprint, ledger, reality</td></tr><tr><td class=\"g-h\">Output</td><td><code>~ paused: false → true</code> — an unexpected change</td></tr><tr><td class=\"g-h\">Owner</td><td>A scheduled plan or the next operator</td></tr><tr><td class=\"g-h\">If it fails</td><td>If nobody runs plan you never know → schedule periodic plans</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ Decide the direction</span><span class=\"g-stage-s\">Fit the blueprint to reality, or reality to the blueprint</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The diff and the reason</td></tr><tr><td class=\"g-h\">Output</td><td>A) edit the blueprint to accept reality / B) apply to revert reality</td></tr><tr><td class=\"g-h\">Owner</td><td>The editor + the owner</td></tr><tr><td class=\"g-h\">If it fails</td><td>Choosing B without asking erases someone’s legitimate hotfix</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">④ Set the rule</span><span class=\"g-stage-s\">“Do not edit in the console”</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>Team agreement</td></tr><tr><td class=\"g-h\">Output</td><td>A hotfix procedure (e.g., reflect in the blueprint within 24 h)</td></tr><tr><td class=\"g-h\">Owner</td><td>Team lead</td></tr><tr><td class=\"g-h\">If it fails</td><td>Without the rule the blueprint drifts from reality and becomes a lie</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>4.3 Failure cases</h4><div class=\"g-tw\"><table><tr><th>Symptom</th><th>Cause</th><th>Prevention</th></tr><tr><td class=\"g-h\">Ledger lost</td><td>It only existed locally</td><td>Remote backend + bucket versioning</td></tr><tr><td class=\"g-h\">Two simultaneous applies</td><td>No locking</td><td>Use a locking backend; wait when locked</td></tr><tr><td class=\"g-h\">Secrets visible in the ledger</td><td>State can hold values in plain text</td><td>Restrict bucket access; reference a secret manager</td></tr><tr><td class=\"g-h\">Hand-editing the ledger</td><td>Editing the file in a hurry</td><td><code>terraform state</code> commands only</td></tr><tr><td class=\"g-h\">Environments share one ledger</td><td>No prefix separation</td><td>A prefix or bucket per environment</td></tr></table></div></section><section class=\"g-topic\"><h4>4.4 Check yourself</h4><details class=\"g-qa\"><summary>How is drift discovered?</summary><div>plan refreshes reality and compares it with blueprint and ledger, showing changes in places you did not touch.</div></details><details class=\"g-qa\"><summary>What does “state may contain secrets” mean in practice?</summary><div>Access to the state bucket is access to those secrets: grant to a minimum set of people and keep access logs.</div></details></section><section class=\"g-topic\"><h4>4.5 Not covered</h4><ul><li>Workspaces and state migration <span class=\"g-badge g-b-warn\">Concept only</span></li><li>State encryption key management <span class=\"g-badge g-b-neutral\">Not covered</span></li></ul></section></div>"}, {"id": "safety", "title": "Safety Rails", "sub": "Ch. 5", "part": "Core", "html": "<div class=\"g-chapter\" id=\"g-tf-safety\"><h3><span class=\"g-cn\">05</span>Safety Rails — Stop Mistakes Before They Happen</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>Safety rails are settings that block accidental deletion and over-broad permissions at the code level: prevent_destroy, least privilege, version pinning, environment separation, and import.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Human attention alone does not stop someone approving a plan that contains a deletion.</div><section class=\"g-topic\"><h4>5.1 Code <span class=\"g-badge g-b-fill\">Advanced</span></h4><p class=\"g-small\">Learning example (fake names)</p><pre><code> 1  terraform {\n 2    required_providers {\n 3      google = { source = \"hashicorp/google\", version = \"~&gt; 6.0\" }\n 4    }\n 5  }\n 6  \n 7  resource \"google_project_iam_member\" \"monitor\" {\n 8    project = \"my-project\"\n 9    role    = \"roles/bigquery.metadataViewer\"\n10    member  = \"serviceAccount:monitor@my-project.iam.gserviceaccount.com\"\n11  }\n12  \n13  resource \"google_storage_bucket\" \"raw_archive\" {\n14    name     = \"my-company-raw-archive\"\n15    location = \"ASIA-NORTHEAST3\"\n16    lifecycle {\n17      prevent_destroy = true\n18    }\n19  }\n20  \n21  import {\n22    to = google_cloud_scheduler_job.ri_sheet_sync\n23    id = \"projects/my-project/locations/asia-northeast3/jobs/ri-sheet-sync\"\n24  }</code></pre><div class=\"g-tw\"><table><tr><th>Line</th><th>What it does</th></tr><tr><td class=\"g-h\">2–4</td><td><b>Version pin</b> — stops the tool from changing one day (~> 6.0 allows 6.x)</td></tr><tr><td class=\"g-h\">7–11</td><td><b>One permission</b> — grants only the read role needed; avoids broad roles like editor/owner (least privilege)</td></tr><tr><td class=\"g-h\">13–19</td><td><b>prevent_destroy = true</b> — Terraform refuses any plan that deletes this bucket; use it on archives and the like</td></tr><tr><td class=\"g-h\">21–24</td><td><b>import</b> — absorb a job already created in the console into the blueprint (Terraform 1.5+)</td></tr></table></div></section><section class=\"g-topic\"><h4>5.2 Three IAM resource styles</h4><div class=\"g-tw\"><table><tr><th>Resource</th><th>Behavior</th><th>Risk</th></tr><tr><td class=\"g-h\"><code>_member</code></td><td><b>Adds</b> one member’s grant</td><td>Low — start here</td></tr><tr><td class=\"g-h\"><code>_binding</code></td><td><b>Overwrites</b> the whole member list of one role</td><td>Anyone not listed loses the role</td></tr><tr><td class=\"g-h\"><code>_policy</code></td><td><b>Overwrites</b> the entire project policy</td><td>Misuse can lock you out</td></tr></table></div></section><section class=\"g-topic\"><h4>5.3 Stage cards — absorbing an existing resource (import)</h4><details class=\"g-stage\"><summary><span class=\"g-stage-t\">① Identify the target</span><span class=\"g-stage-s\">Find the ID of the console resource</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>Resource info from the console or CLI</td></tr><tr><td class=\"g-h\">Output</td><td>The ID string for import</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator</td></tr><tr><td class=\"g-h\">If it fails</td><td>ID formats vary per resource; check the import section of its docs</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② Write the import block and blueprint</span><span class=\"g-stage-s\">Write it with the same values as the existing resource</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The ID from ①</td></tr><tr><td class=\"g-h\">Output</td><td>An import block and a resource block</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator</td></tr><tr><td class=\"g-h\">If it fails</td><td>Mismatched values show up as changes right after import</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ Iterate until plan shows no changes</span><span class=\"g-stage-s\">Fit the blueprint to reality until they match</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The diff in plan</td></tr><tr><td class=\"g-h\">Output</td><td><code>No changes.</code></td></tr><tr><td class=\"g-h\">Owner</td><td>Operator + reviewer</td></tr><tr><td class=\"g-h\">If it fails</td><td>Applying the diff changes live values — during import fix the blueprint instead</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>5.4 Failure cases</h4><div class=\"g-tw\"><table><tr><th>Symptom</th><th>Cause</th><th>Prevention</th></tr><tr><td class=\"g-h\">Permissions vanish</td><td><code>_binding</code>/_policy overwrote them</td><td><code>_member</code> and check removed members in plan</td></tr><tr><td class=\"g-h\">Bucket deletion refused at apply</td><td>prevent_destroy working as intended</td><td>Lift it only for real deletions, with review</td></tr><tr><td class=\"g-h\">Plan changed after upgrading</td><td>Versions unpinned</td><td>Commit required_providers and .terraform.lock.hcl</td></tr><tr><td class=\"g-h\">Dev values applied to prod</td><td>No environment separation</td><td>Per-env variable files, state prefixes, separate accounts</td></tr></table></div></section><section class=\"g-topic\"><h4>5.5 Check yourself</h4><details class=\"g-qa\"><summary>What if you truly must delete a prevent_destroy resource?</summary><div>Lift it temporarily, review the plan, then delete. The protection is a deliberate speed bump, not a nuisance.</div></details><details class=\"g-qa\"><summary>What if plan shows changes right after an import?</summary><div>Your blueprint differs from reality; do not apply — adjust the blueprint to match.</div></details></section><section class=\"g-topic\"><h4>5.6 Not covered</h4><ul><li>Organization policies <span class=\"g-badge g-b-neutral\">Not covered</span></li><li>Service account key management <span class=\"g-badge g-b-neutral\">Not covered</span></li></ul></section></div>"}, {"id": "adopt", "title": "Adoption Steps", "sub": "Ch. 6", "part": "Operations", "html": "<div class=\"g-chapter\" id=\"g-tf-adopt\"><h3><span class=\"g-cn\">06</span>Adoption Steps — Riskiest First, Not All at Once</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>Adoption is not a big-bang change; it is a sequence of moving the riskiest resources into blueprints first and then forbidding console edits for what has moved.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Half-moved, the blueprint diverges from reality and lies — more confusing than using only the console.</div><section class=\"g-topic\"><h4>6.1 What goes into a blueprint</h4><div class=\"g-tw\"><table><tr><th>Kind</th><th>Verdict</th><th>Why</th></tr><tr><td class=\"g-h\">Permissions (IAM)</td><td>Move first</td><td>Silent drift is costly and history matters most</td></tr><tr><td class=\"g-h\">Scheduled jobs</td><td>Move first</td><td>Paused jobs are often recorded nowhere</td></tr><tr><td class=\"g-h\">Networking and firewalls</td><td>Move</td><td>Mistakes have a wide blast radius</td></tr><tr><td class=\"g-h\">Data stores</td><td>Move with prevent_destroy</td><td>Deletion is irreversible</td></tr><tr><td class=\"g-h\">One-off experiments</td><td>Leave out</td><td>Short-lived; the blueprint goes stale</td></tr><tr><td class=\"g-h\">Frequently changing app deploys</td><td>Other tooling</td><td>CI/CD territory</td></tr></table></div></section><section class=\"g-topic\"><h4>6.2 Stage cards — the adoption sequence</h4><details class=\"g-stage\" open><summary><span class=\"g-stage-t\">① Set the scope</span><span class=\"g-stage-s\">Pick 10–15 resources this round</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The table in 6.1 and the current resource list</td></tr><tr><td class=\"g-h\">Output</td><td>A move list with owners</td></tr><tr><td class=\"g-h\">Owner</td><td>Team lead</td></tr><tr><td class=\"g-h\">If it fails</td><td>A big scope exhausts you during import</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">② Create the ledger</span><span class=\"g-stage-s\">Remote backend and access control</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The setup in 4.1</td></tr><tr><td class=\"g-h\">Output</td><td>A shared ledger and a minimal access list</td></tr><tr><td class=\"g-h\">Owner</td><td>Platform owner</td></tr><tr><td class=\"g-h\">If it fails</td><td>A local ledger blocks team adoption at the start</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">③ Import</span><span class=\"g-stage-s\">Repeat the 5.3 procedure per resource</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The move list</td></tr><tr><td class=\"g-h\">Output</td><td>A plan that says No changes</td></tr><tr><td class=\"g-h\">Owner</td><td>Operator</td></tr><tr><td class=\"g-h\">If it fails</td><td>The messiest, slowest part; split it into daily chunks</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">④ Automated plan</span><span class=\"g-stage-s\">Run a plan on every PR and show it</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>A blueprint-change PR</td></tr><tr><td class=\"g-h\">Output</td><td>A plan for the reviewer</td></tr><tr><td class=\"g-h\">Owner</td><td>CI</td></tr><tr><td class=\"g-h\">If it fails</td><td>Automate apply last; automate plan first</td></tr></table></div></div></details><details class=\"g-stage\"><summary><span class=\"g-stage-t\">⑤ Declare the rule</span><span class=\"g-stage-s\">No console edits for moved resources</span></summary><div class=\"g-stage-b\"><div class=\"g-tw\"><table><tr><td class=\"g-h\">Input</td><td>The hotfix procedure from 4.2 ④</td></tr><tr><td class=\"g-h\">Output</td><td>A team doc and periodic plan checks</td></tr><tr><td class=\"g-h\">Owner</td><td>Everyone</td></tr><tr><td class=\"g-h\">If it fails</td><td>Once the rule breaks, the blueprint soon diverges</td></tr></table></div></div></details></section><section class=\"g-topic\"><h4>6.3 Counter-evidence — what Terraform cannot stop</h4><div class=\"g-trap\"><b class=\"g-l\">Limits of scope</b>App-level 500 errors, network outages, and changes to resources absent from the blueprint are not stopped by Terraform. It is not a tool that makes outages disappear; it guarantees the containers match the blueprint. App health belongs to monitoring.</div></section><section class=\"g-topic\"><h4>6.4 Check yourself</h4><details class=\"g-qa\"><summary>Why migrate permissions and scheduled jobs first?</summary><div>They drift silently and take long to notice, so a change history is most valuable there.</div></details></section><section class=\"g-topic\"><h4>6.5 Not covered</h4><ul><li>Large multi-account/org rollouts <span class=\"g-badge g-b-danger\">Depends</span></li><li>Designing auto-apply pipelines <span class=\"g-badge g-b-warn\">Concept only</span></li></ul></section></div>"}, {"id": "vibe", "title": "Instructing an AI", "sub": "Ch. 7", "part": "Advanced", "html": "<div class=\"g-chapter\" id=\"g-tf-vibe\"><h3><span class=\"g-cn\">07</span>Instructing an AI — Known Terms Mean Less Wandering</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>AI writes Terraform well but does not know what it must not touch unless told. The keywords here are constraints that steer it toward safe changes instead of delete-and-recreate code.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Without constraints the AI returns the most common example — which creates anew or grants broad permissions.</div><section class=\"g-topic\"><h4>7.1 Keyword dictionary</h4><div class=\"g-tw\"><table><tr><th>Keyword</th><th>Meaning</th><th>What changes</th></tr><tr><td class=\"g-h\">terraform plan only, do not apply</td><td>Preview only</td><td>No real changes are made</td></tr><tr><td class=\"g-h\">import existing resources</td><td>Absorb what exists</td><td>Avoids creating and colliding</td></tr><tr><td class=\"g-h\">no destroy / prevent_destroy</td><td>No deletions</td><td>Blocks deleting plans</td></tr><tr><td class=\"g-h\">remote state on GCS backend</td><td>Ledger in a shared place</td><td>Prevents divergent ledgers</td></tr><tr><td class=\"g-h\">least privilege IAM, use _member only</td><td>Least privilege, additive only</td><td>Avoids broad roles and overwrites</td></tr><tr><td class=\"g-h\">drift detection / plan -refresh-only</td><td>Detect manual edits</td><td>Shows how to find console changes</td></tr><tr><td class=\"g-h\">pin provider version, commit lock file</td><td>Pin tool versions</td><td>Prevents sudden behavior changes</td></tr><tr><td class=\"g-h\">moved block for rename</td><td>Declare a rename</td><td>Moves instead of delete+create</td></tr></table></div></section><section class=\"g-topic\"><h4>7.2 Same request, different result</h4><div class=\"g-grid2\"><div class=\"g-trap\"><b class=\"g-l\">Prompt that wanders</b><br>Create a cloud scheduler with Terraform</div><div class=\"g-key g-okkey\"><b class=\"g-l\">Prompt that stays on track</b><br>Write Terraform that absorbs the existing Cloud Scheduler job ri-sheet-sync in GCP project my-project using an import block. Pin the google provider version and use a GCS backend for state. Show how to confirm zero changes using plan only — do not use apply or destroy.</div></div><p class=\"g-small\">Why it differs: Saying “already exists” and “plan only” keeps the AI from planning to create or delete.</p><div class=\"g-grid2\"><div class=\"g-trap\"><b class=\"g-l\">Prompt that wanders</b><br>Give the monitor BigQuery access</div><div class=\"g-key g-okkey\"><b class=\"g-l\">Prompt that stays on track</b><br>The monitor service account only needs to read BigQuery metadata. Add just roles/bigquery.metadataViewer with google_project_iam_member and no broader role. Also tell me what to check in the plan output.</div></div><p class=\"g-small\">Why it differs: Stating least privilege precisely stops the AI from reflexively granting broad roles like editor.</p></section><section class=\"g-topic\"><h4>7.3 A prompt template</h4><ol><li><b>What</b>: the resource to create or change, in one line</li><li><b>Current state</b>: does it exist (import)? Where is the ledger?</li><li><b>Forbidden</b>: no apply/destroy, no broad permissions, no deleting existing resources</li><li><b>Safety</b>: version pin, prevent_destroy targets</li><li><b>Verification</b>: what to check in the plan (destroy 0, no replacement)</li></ol></section><section class=\"g-topic\"><h4>7.4 Review an AI-written blueprint</h4><ul class=\"g-checklist\"><li>Is destroy 0 on the plan’s last line?</li><li>Are there no -/+ replacements?</li><li>Are roles only as broad as needed?</li><li>Is the ledger in a shared bucket (GCS)?</li><li>Are there no secrets or keys in the code?</li><li>Does apply happen only after a human reads the plan?</li></ul><div class=\"g-trap\"><b class=\"g-l\">The most important rule</b>By default, tell the AI “plan only”. An irreversible apply happens only after a human reads and approves the plan.</div></section><section class=\"g-topic\"><h4>7.5 Not covered</h4><ul><li>Tool-specific usage of any AI product <span class=\"g-badge g-b-neutral\">Not covered</span></li></ul></section></div>"}, {"id": "limits", "title": "Out of Scope and Choices", "sub": "Ch. 8", "part": "Boundaries", "html": "<div class=\"g-chapter\" id=\"g-tf-limits\"><h3><span class=\"g-cn\">08</span>Out of Scope and Choices</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>This chapter gathers, openly, what the book leaves out and the choices whose answers depend on context.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Hidden boundaries read as “not in the book, so unnecessary” — and those are exactly what production omits first.</div><section class=\"g-topic\"><h4>8.1 Not covered</h4><div class=\"g-tw\"><table><tr><th>Topic</th><th>Status</th><th>Where to look</th></tr><tr><td class=\"g-h\">Full HCL syntax and functions</td><td><span class=\"g-badge g-b-neutral\">Not covered</span></td><td>Official language docs</td></tr><tr><td class=\"g-h\">Module design</td><td><span class=\"g-badge g-b-warn\">Concept only</span></td><td>Official module guide</td></tr><tr><td class=\"g-h\">Policy checks and approval workflows</td><td><span class=\"g-badge g-b-neutral\">Not covered</span></td><td>Sentinel / OPA</td></tr><tr><td class=\"g-h\">Terraform Cloud / managed runs</td><td><span class=\"g-badge g-b-neutral\">Not covered</span></td><td>HashiCorp docs</td></tr></table></div></section><section class=\"g-topic\"><h4>8.2 Undecided — it depends</h4><div class=\"g-tw\"><table><tr><th>Question</th><th>Decision criteria</th></tr><tr><td class=\"g-h\">Terraform vs. OpenTofu vs. Pulumi</td><td>Team language preference, licensing, existing assets (<span class=\"g-badge g-b-danger\">Depends</span>)</td></tr><tr><td class=\"g-h\">Use automatic apply?</td><td>Only when risk, approvals, and rollback are in place</td></tr><tr><td class=\"g-h\">Environment separation (folders vs. workspaces)</td><td>How different environments are, and team size</td></tr></table></div></section></div>"}, {"id": "ref", "title": "Glossary, Sources, Revisions", "sub": "Ch. 9", "part": "Appendix", "html": "<div class=\"g-chapter\" id=\"g-tf-ref\"><h3><span class=\"g-cn\">09</span>Glossary · Sources · Revisions</h3><div class=\"g-key\"><b class=\"g-l\">Definition</b>This chapter collects every term in Korean and English, and records the sources behind technical claims and the document’s revision history.</div><div class=\"g-trap\"><b class=\"g-l\">Without it</b>Scattered terms get understood differently per chapter; without sources, errors have nowhere to be corrected.</div><section class=\"g-topic\"><h4>9.1 Glossary</h4><div class=\"g-tw\"><table><tr><th>Term</th><th>Definition</th></tr><tr><td class=\"g-h\">Blueprint</td><td>The .tf files describing the desired state</td></tr><tr><td class=\"g-h\">IaC</td><td>Infrastructure as Code</td></tr><tr><td class=\"g-h\">provider</td><td>The plugin that talks to a cloud</td></tr><tr><td class=\"g-h\">resource</td><td>One resource to create</td></tr><tr><td class=\"g-h\">state</td><td>The ledger file of what Terraform believes exists</td></tr><tr><td class=\"g-h\">plan</td><td>A preview that computes changes without making any</td></tr><tr><td class=\"g-h\">apply</td><td>Making approved changes real</td></tr><tr><td class=\"g-h\">drift</td><td>When reality diverges from blueprint and ledger</td></tr><tr><td class=\"g-h\">import</td><td>Absorbing an existing resource into blueprint and ledger</td></tr><tr><td class=\"g-h\">replace (-/+)</td><td>Delete and recreate under the same name</td></tr><tr><td class=\"g-h\">prevent_destroy</td><td>A protection that rejects plans that delete</td></tr><tr><td class=\"g-h\">backend</td><td>Where the ledger is stored</td></tr><tr><td class=\"g-h\">lock</td><td>A ledger lock allowing only one apply at a time</td></tr><tr><td class=\"g-h\">least privilege</td><td>Granting only the permissions required</td></tr><tr><td class=\"g-h\">module</td><td>A reusable bundle of blueprint code</td></tr></table></div></section><section class=\"g-topic\"><h4>9.2 Sources</h4><ol class=\"g-sources\"><li><a href=\"https://developer.hashicorp.com/terraform/intro\">What is Terraform</a> — Concept overview</li><li><a href=\"https://developer.hashicorp.com/terraform/cli/commands/plan\">terraform plan</a> — Reading plans; -detailed-exitcode</li><li><a href=\"https://developer.hashicorp.com/terraform/language/import\">Import</a> — The import block (1.5+)</li><li><a href=\"https://developer.hashicorp.com/terraform/language/state\">State</a> — State, locking, sensitive values</li><li><a href=\"https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle\">lifecycle</a> — prevent_destroy</li><li><a href=\"https://registry.terraform.io/providers/hashicorp/google/latest/docs/resources/google_project_iam\">google_project_iam</a> — Differences among _member, _binding, _policy</li></ol><p>Commands and options vary by version; check your version’s docs before practicing. That state may hold sensitive values in plain text is based on the State documentation.</p></section><section class=\"g-topic\"><h4>9.3 A first exercise</h4><ol><li>In a personal sandbox project, create one bucket from a blueprint (<span class=\"g-badge g-b-ok\">Hands-on</span>)</li><li><code>plan</code> to read the preview, then <code>apply</code></li><li>Change a bucket label by hand in the console</li><li>Run plan again and see the manual edit caught</li><li>Align the blueprint with reality until it says No changes</li></ol></section><section class=\"g-topic\"><h4>9.4 Revision history</h4><div class=\"g-tw\"><table><tr><th>Version</th><th>Date</th><th>Change</th></tr><tr><td class=\"g-h\">v0.2</td><td>2026-10-15</td><td>Full rewrite into a fixed frame. Korean and English together. Company-specific cases replaced with generic examples.</td></tr><tr><td class=\"g-h\">v0.1</td><td>2026-10-14</td><td>First draft (concept-centered intro, Korean)</td></tr></table></div></section></div>"}];
